5	// A rejected scenario earns a description of what the office objected to —
6	// not a stack trace — and nothing at all on stdout.
7	try {
8	  const scenario = JSON.parse(await text(process.stdin)) as Scenario;
9	  process.stdout.write(JSON.stringify(runScenario(scenario)));
10	} catch (error) {
11	  process.stderr.write(`${(error as Error).message}\n`);
12	  process.exitCode = 1;
