1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	import { fileURLToPath } from "node:url";
4	
5	const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));
6	
7	type CliRun = { stdout: string; stderr: string; code: number };
8	
9	// The CLI is exercised as a real subprocess so that stdin, stdout and the
10	// exit code — the whole of its contract — are genuinely under test.
11	const runCli = (input: string): Promise<CliRun> =>
12	  new Promise((resolve, reject) => {
13	    const child = spawn("npx", ["tsx", CLI], { stdio: ["pipe", "pipe", "pipe"] });
14	    let stdout = "";
15	    let stderr = "";
16	
17	    child.stdout.on("data", (chunk) => (stdout += chunk));
18	    child.stderr.on("data", (chunk) => (stderr += chunk));
19	    child.on("error", reject);
20	    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));
21	
22	    child.stdin.end(input);
23	  });
24	
25	describe("claim-office CLI", () => {
26	  it(
27	    "reads a scenario from stdin and writes {results: [...]} to stdout",
28	    async () => {
29	      const scenario = {
30	        customer: { yearsWithMHPCO: 5 },
31	        steps: [
32	          {
33	            op: "quote",
34	            items: [
35	              { type: "amulet", material: "silver", enchantment: 2, cursed: false },
36	            ],
37	          },
38	          {
39	            op: "claim",
40	            policy: 0,
41	            incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
42	          },
43	        ],
44	      };
45	
46	      const { stdout, code } = await runCli(JSON.stringify(scenario));
47	
48	      expect(code).toBe(0);
49	      expect(JSON.parse(stdout)).toEqual({
50	        results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
51	      });
52	    },
53	    30000,
54	  );
55	
56	  it(
57	    "writes one result per step, in the same order as the input steps",
58	    async () => {
59	      const scenario = {
60	        customer: { yearsWithMHPCO: 0 },
61	        steps: [
62	          {
63	            op: "quote",
64	            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
65	          },
66	          {
67	            op: "quote",
68	            items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
69	          },
70	          {
71	            op: "claim",
72	            policy: 0,
73	            incident: { cause: "fire", damages: [{ itemType: "sword", amount: 300 }] },
74	          },
75	          {
76	            op: "claim",
77	            policy: 1,
78	            incident: { cause: "theft", damages: [{ itemType: "amulet", amount: 500 }] },
79	          },
80	        ],
81	      };
82	
83	      const { stdout, code } = await runCli(JSON.stringify(scenario));
84	      const { results } = JSON.parse(stdout);
85	
86	      expect(code).toBe(0);
87	      expect(results).toHaveLength(4);
88	      expect(results).toEqual([
89	        { premium: 115 },
90	        { premium: 62 },
91	        { payout: 200, remainingCap: 1800 },
92	        { payout: 400, remainingCap: 800 },
93	      ]);
94	    },
95	    30000,
96	  );
97	  // Result shapes per step type — {premium} vs {payout, remainingCap} — are
98	  // asserted exactly by the ordering test above.
99	  it(
100	    "exits with a non-zero status and writes to stderr on an unknown item type",
101	    async () => {
102	      const scenario = {
103	        customer: { yearsWithMHPCO: 0 },
104	        steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
105	      };
106	
107	      const { stdout, stderr, code } = await runCli(JSON.stringify(scenario));
108	
109	      expect(code).not.toBe(0);
110	      expect(stderr).toMatch(/broomstick/i);
111	      expect(stdout.trim()).toBe("");
112	      // A description of the problem, not a stack trace dumped at the customer.
113	      expect(stderr).not.toMatch(/^\s*at\s/m);
114	    },
115	    30000,
116	  );
117	  it.todo("exits with a non-zero status and writes to stderr on an invalid claim");
118	  it.todo("writes no results to stdout when the scenario is rejected");
119	});
